import{_ as e,o as t,c as r,a5 as o}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"JD5 字符个数统计","description":"描述 编写一个函数，计算字符串中含有的不同字符的个数。字符在 ASCII 码范围内( 0 127 ，包括 0 和 127 )，换行表示结束符，不算在字符里。不在范围内的不作统计。多个相同的字符只计算一次 例如，对于字符串 abaca 而言，有 a、b、c 三种不同的字符，因此输出。","frontmatter":{"title":"JD5 字符个数统计","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 编写一个函数，计算字符串中含有的不同字符的个数。字符在 ASCII 码范围内( 0 127 ，包括 0 和 127 )，换行表示结束符，不算在字符里。不在范围内的不作统计。多个相同的字符只计算一次 例如，对于字符串 abaca 而言，有 a、b、c 三种不同的字符，因此输出。","sidebarWeight":80,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/JD5 字符个数统计.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD5 字符个数统计.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD5 字符个数统计.md"}'),s={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD5 字符个数统计.md"};function n(i,a,c,d,l,_){return t(),r("div",null,[...a[0]||(a[0]=[o('<div><h1 id="jd5-字符个数统计" tabindex="-1">JD5 字符个数统计 <a class="header-anchor" href="#jd5-字符个数统计" aria-label="Permalink to &quot;JD5 字符个数统计&quot;">​</a></h1><blockquote><p>本节目标：理解“JD5 字符个数统计”的核心思路，并能把它用于实际开发或面试表达。 <strong>描述</strong> 编写一个函数，计算字符串中含有的不同字符的个数。字符在 ASCII 码范围内( 0~127 ，包括 0 和 127 )，换行表示结束符，不算在字符里。不在范围内的不作统计。多个相同的字符只计算一次 例如，对于字符串 abaca 而言，有 a、b、c 三种不同的字符，因此输出 3 。 数据范围： 1≤�≤500 1≤<em>n</em>≤500 <strong>输入描述：</strong> 输入一行没有空格的字符串。 <strong>输出描述：</strong> 输出 输入字符串 中范围在(0~127，包括0和127)字符的种数。 <strong>示例1</strong> 输入： abc ==复制== 输出： 3 ==复制== <strong>示例2</strong> 输入： aaa ==复制== 输出： 1 ==复制==</p></blockquote><p>def count_unique_chars(s):</p><h1 id="使用集合来自动去重-并筛选出ascii码在0-127之间的字符" tabindex="-1">使用集合来自动去重，并筛选出ASCII码在0~127之间的字符 <a class="header-anchor" href="#使用集合来自动去重-并筛选出ascii码在0-127之间的字符" aria-label="Permalink to &quot;使用集合来自动去重，并筛选出ASCII码在0~127之间的字符&quot;">​</a></h1><p>unique_chars = {char for char in s if 0 &lt;= ord(char) &lt;= 127}</p><h1 id="返回集合中元素的数量-即不同字符的个数" tabindex="-1">返回集合中元素的数量，即不同字符的个数 <a class="header-anchor" href="#返回集合中元素的数量-即不同字符的个数" aria-label="Permalink to &quot;返回集合中元素的数量，即不同字符的个数&quot;">​</a></h1><p>return len(unique_chars)</p><h1 id="读取输入字符串" tabindex="-1">读取输入字符串 <a class="header-anchor" href="#读取输入字符串" aria-label="Permalink to &quot;读取输入字符串&quot;">​</a></h1><p>input_str = input()</p><h1 id="计算并输出不同字符的个数" tabindex="-1">计算并输出不同字符的个数 <a class="header-anchor" href="#计算并输出不同字符的个数" aria-label="Permalink to &quot;计算并输出不同字符的个数&quot;">​</a></h1><p>print(count_unique_chars(input_str))</p></div>',1)])])}const p=e(s,[["render",n]]);export{u as __pageData,p as default};
